class Node {
    constructor(value, next = null, prev = null) {
        this.value = value;
        this.next = next;
        this.prev = prev;
    }
}

class LinkedList {
    constructor() {
        this.head = null;
        this.tail = null;
        this.length = 0;
    }

    push(value) {
        const node = new Node(value, null, this.tail);
        if (this.tail) this.tail.next = node; else this.head = node;
        this.tail = node;
        this.length++;
    }

    pop() {
        const node = this.tail;
        this.tail = node.prev;
        if (this.tail) this.tail.next = null; else this.head = null;
        this.length--;
        return node.value;
    }

    shift() {
        const node = this.head;
        this.head = node.next;
        if (this.head) this.head.prev = null; else this.tail = null;
        this.length--;
        return node.value;
    }

    unshift(value) {
        const node = new Node(value, this.head, null);
        if (this.head) this.head.prev = node; else this.tail = node;
        this.head = node;
        this.length++;
    }

    delete(value) {
        for (let node = this.head; node; node = node.next) {
            if (node.value === value) {
                if (node.prev) node.prev.next = node.next; else this.head = node.next;
                if (node.next) node.next.prev = node.prev; else this.tail = node.prev;
                this.length--;
                return;
            }
        }
    }

    count() {
        return this.length;
    }
}

